/**
 * Nexora demo data — the single source of truth for every mocked page.
 *
 * Demo orders are generated by the same routing simulator used by routing demonstrations. They
 * are fixtures only; live Orders, Dashboard, Analytics and Capacity routes use the Laravel API.
 * Everything is deterministic — the same seed always yields the same data.
 *
 * This is clearly-labelled demonstration data. Production routes use the authenticated Laravel API.
 */
import { LOCATIONS, LOCATION_TYPE_LABEL } from './locations-data.js';
import { simulateRouting } from '../utils/routingSimulator.js';

export { LOCATIONS, LOCATION_TYPE_LABEL };

const NOW = Date.now();
const DAY = 86_400_000;
export const daysAgo = (n) => new Date(NOW - n * DAY).toISOString();

/** Deterministic pseudo-random in [0,1) from an integer seed. */
const r = (seed) => ((seed * 9301 + 49297) % 233280) / 233280;
const pick = (arr, seed) => arr[Math.floor(r(seed) * arr.length) % arr.length];

// ---------------------------------------------------------------------------
// Orders — generated deterministically via the shared simulator.
// ---------------------------------------------------------------------------

const CUSTOMERS = [
  ['Aisha Khan', 'Karachi', 'PK'], ['Liam Walsh', 'London', 'GB'],
  ['Emma Johnson', 'New York', 'US'], ['Noah Smith', 'Chicago', 'US'],
  ['Sofia Rossi', 'Milan', 'IT'], ['Omar Farooq', 'Lahore', 'PK'],
  ['Chloe Martin', 'Paris', 'FR'], ['Lucas Meyer', 'Berlin', 'DE'],
  ['Ava Wilson', 'Los Angeles', 'US'], ['Hannah Bauer', 'Amsterdam', 'NL'],
];

const PRODUCTS = [
  ['Linen Shirt', 'apparel'], ['Ceramic Mug', 'fragile'], ['Wireless Earbuds', 'electronics'],
  ['Denim Jacket', 'apparel'], ['Glass Carafe', 'fragile'], ['Desk Lamp', 'electronics'],
  ['Wool Scarf', 'apparel'], ['Phone Case', 'electronics'],
];

const ROUTED_STATUSES = ['routed', 'routed', 'routed', 'routed', 'rerouted', 'pending'];
const FULFILMENT_STATUSES = ['fulfilled', 'fulfilled', 'pending', 'unfulfilled'];

// A few orders are deliberately unroutable, to exercise the manual-review flows.
const FORCE_REVIEW = new Set([5, 17]);

function buildOrder(i) {
  const [customer, city, country] = CUSTOMERS[i % CUSTOMERS.length];
  const itemCount = 1 + (i % 3);
  const items = Array.from({ length: itemCount }, (_, k) => {
    const [title, tag] = PRODUCTS[(i + k) % PRODUCTS.length];
    return { title, tag, qty: 1 + ((i + k) % 2), sku: `NX-${100 + ((i + k) % PRODUCTS.length)}` };
  });

  const order = {
    id: `ord-${1001 + i}`,
    number: `#${1001 + i}`,
    date: daysAgo(i % 12),
    customer,
    destination: { city, country },
    itemCount,
    items,
  };

  const sim = simulateRouting(order, LOCATIONS, { objective: 'lowest_cost', excludeOverloaded: false });
  const candidates = sim.ranked.map((c) => ({
    locationId: c.locationId,
    eligible: c.eligible,
    shippingEstimate: c.shippingEstimate,
    reason: c.reasons[0] ?? 'Eligible',
  }));

  // Forced-review orders: nothing is eligible, so Order Details and the status agree.
  if (FORCE_REVIEW.has(i) || !sim.selected) {
    const blocked = candidates.map((c) => ({ ...c, eligible: false, reason: 'At or above daily capacity' }));
    return {
      ...order,
      candidates: blocked,
      assignedLocationId: null,
      shippingEstimate: null,
      baselineLocationId: blocked[0]?.locationId ?? null,
      baselineEstimate: blocked[0]?.shippingEstimate ?? null,
      savings: 0,
      split: false,
      splitPenalty: 0,
      shipments: [],
      routingStatus: 'needs_review',
      fulfillmentStatus: 'unfulfilled',
      ruleId: 'rule-overload',
      decisionReason: 'No location passed every rule and capacity check for this order.',
    };
  }

  const selected = sim.selected;
  const eligible = sim.ranked.filter((c) => c.eligible);
  // Baseline = the most expensive ELIGIBLE route we could have shipped from (what you'd pay without
  // cost-aware routing). If only one is eligible, savings are zero — reported honestly.
  const baseline = eligible[eligible.length - 1];
  const fragile = items.some((it) => it.tag === 'fragile');
  const split = itemCount === 3 && i % 5 === 0 && eligible.length > 1;
  const second = eligible[1] ?? selected;

  return {
    ...order,
    candidates,
    assignedLocationId: selected.locationId,
    shippingEstimate: selected.shippingEstimate,
    baselineLocationId: baseline.locationId,
    baselineEstimate: baseline.shippingEstimate,
    savings: Number((baseline.shippingEstimate - selected.shippingEstimate).toFixed(2)),
    split,
    splitPenalty: split ? 4.5 : 0,
    shipments: split
      ? [
        { locationId: selected.locationId, items: items.slice(0, 1).map((it) => it.title) },
        { locationId: second.locationId, items: items.slice(1).map((it) => it.title) },
      ]
      : [{ locationId: selected.locationId, items: items.map((it) => it.title) }],
    routingStatus: ROUTED_STATUSES[i % ROUTED_STATUSES.length],
    fulfillmentStatus: pick(FULFILMENT_STATUSES, i + 3),
    ruleId: fragile ? 'rule-fragile' : 'rule-cost',
    decisionReason: sim.explanation,
  };
}

export const ORDERS = Array.from({ length: 28 }, (_, i) => buildOrder(i));

